// BATCH VERIFIER: batch_verifier.go
func (s *Service) validateWithKzgBatchVerifier(ctx context.Context, dataColumns []blocks.RODataColumn) (pubsub.ValidationResult, error) {
    timeout := time.Duration(params.BeaconConfig().SecondsPerSlot) * time.Second
    resChan := make(chan error)
    verificationSet := &kzgVerifier{dataColumns: dataColumns, resChan: resChan}
    s.kzgChan <- verificationSet
    ctx, cancel := context.WithTimeout(ctx, timeout)
    defer cancel()
    select {
    case <-ctx.Done():
        return pubsub.ValidationIgnore, ctx.Err()
    case err := <-resChan:
        if err != nil {
            return s.validateUnbatchedColumnsKzg(ctx, dataColumns)
        }
    }
    return pubsub.ValidationAccept, nil
}

// RPC VERIFICATION PATH (data_column_sidecars.go)
func verifyByRootDataColumnSidecars(newVerifier verification.NewDataColumnsVerifier, roDataColumns []blocks.RODataColumn) ([]blocks.VerifiedRODataColumn, error) {
    verifier := newVerifier(roDataColumns, verification.ByRootRequestDataColumnSidecarRequirements)
    if err := verifier.ValidFields(); err != nil { return nil, errors.Wrap(err, "valid fields") }
    if err := verifier.SidecarInclusionProven(); err != nil { return nil, errors.Wrap(err, "sidecar inclusion proven") }
    if err := verifier.SidecarKzgProofVerified(); err != nil { return nil, errors.Wrap(err, "sidecar KZG proof verified") }
    verifiedRoDataColumns, err := verifier.VerifiedRODataColumns()
    return verifiedRoDataColumns, err
}

